PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbp: <http://dbpedia.org/property/>

SELECT ?film ?director ?birthDate WHERE {
  VALUES ?film { dbr:Lithivm dbr:Romeo.Juliet }

  # Prefer a DBPedia property when it yields an IRI (i.e., a proper Person URI)
  OPTIONAL { ?film dbp:director ?dirDBP . FILTER(isIRI(?dirDBP)) }
  OPTIONAL { ?film dbo:director ?dirDBO . }

  BIND (COALESCE(?dirDBP, ?dirDBO) AS ?director)

  ?director dbo:birthDate ?birthDate .
}
LIMIT 100

